/** Exact-label, manually reviewed additions. No automatic gazetteer aliases or geocoding. */
function place(label:string,contemporaryName:string,latitude:number,longitude:number,title:string,url:string,note='نقطة استدلال للمدينة في المرجع الجغرافي؛ ليست موضع مسكن المؤلف أو قبره، ولا تحدد حدود المدينة القديمة.'){
 return Object.freeze({label,contemporaryName,latitude,longitude,zoom:12,note,sources:Object.freeze([{title,url}])})
}
function country(label:string,latitude:number,longitude:number,zoom:number,title:string,url:string){return Object.freeze({...place(label,`${label} المعاصرة — نظرة عامة`,latitude,longitude,title,url,'نظرة عامة بنقطة مرجعية للدولة المعاصرة؛ ليست مدينة أو مسكن مؤلف، ولا تمثل بالضرورة الامتداد التاريخي للاسم أو الحدود السياسية في زمن المؤلف.'),zoom})}
